using Commerce;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Commerce.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem / GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_SingleItem_TotalEqualsPrice()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);
        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_TotalMultiplies()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);
        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleItems_TotalSumsAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);
        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingSku_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 5.00m, 2);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_RemovesThenGetTotal_ReturnsZero()
    {
        _cart.AddItem("SKU-001", 7.50m, 2);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // --- Edge cases ---

    [TestMethod]
    public void AddItem_ZeroQuantity_DoesNotAffectTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 0);
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_BothCounted()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 1);
        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAll()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0m, _cart.GetTotal());
    }
}

